from pathlib import Path
import re,collections
lines=Path('/workspace/outputs/train.log').read_text(errors='replace').splitlines()
patterns={
 'traceback':r'Traceback','exception':r'(?i)exception','error':r'(?i)(?:\berror\b|runtimeerror|error:)','warning':r'(?i)\bwarn(?:ing)?\b','failed':r'(?i)\bfail(?:ed|ure)?\b','oom':r'(?i)(?:out of memory|\boom\b)','nan':r'(?<![A-Za-z])(?:nan|inf)(?![A-Za-z])','timeout':r'(?i)(?:timeout|timed out)','killed':r'(?i)\bkilled\b'}
for name,pat in patterns.items():
 rx=re.compile(pat)
 hits=[(i,s,rx.search(s)) for i,s in enumerate(lines,1) if rx.search(s)]
 print('\nCATEGORY',name,'LINES',len(hits))
 for i,s,m in hits[:60]:
  a=max(0,m.start()-130); b=min(len(s),m.end()+300)
  print(i,repr(s[a:b]))
 if len(hits)>60: print('... remaining',len(hits)-60)
