python -I -c 'import json,re,math,statistics,collections
paths=[f"/workspace/outputs/frozen_eval/{s}.jsonl" for s in (0,150)]+[f"/workspace/outputs/rollouts/{s}.jsonl" for s in (1,75,150)]
def q(a,p):
 a=sorted(a); z=(len(a)-1)*p; i=int(z); f=z-i
